// ============================================
// VALIDATE INPUT (RFC-004 Phase 2)
// ============================================

const input = $input.first().json;
const body = input.body || {};
const headers = input.headers || {};

// --- Extraction Project ID ---
const projectId = headers['x-project-id'] 
  || headers['X-Project-ID'] 
  || headers['X-Project-Id']
  || body.project_id
  || 'unknown';

// --- Validate required fields ---
if (!body.discord_user_id) {
  return {
    error: true,
    error_code: 'MISSING_USER_ID',
    message: 'Le champ "discord_user_id" est requis'
  };
}

if (!body.guild_id) {
  return {
    error: true,
    error_code: 'MISSING_GUILD_ID',
    message: 'Le champ "guild_id" est requis'
  };
}

if (!body.old_channel_id) {
  return {
    error: true,
    error_code: 'MISSING_OLD_CHANNEL_ID',
    message: 'Le champ "old_channel_id" (channel supprimé) est requis'
  };
}

// --- Return validated data ---
return {
  error: false,
  data: {
    discord_user_id: body.discord_user_id,
    guild_id: body.guild_id,
    old_channel_id: body.old_channel_id,
    channel_type: body.channel_type || 'support',
    project_id: projectId,
    metadata: body.metadata || {}
  }
};

// ============================================
// PREPARE REDIS STREAM MESSAGE FOR NEW CHANNEL
// ============================================

const validationData = $('Validate Input').first().json.data;
const deleteResult = $input.first().json;

// Callback URL for chatbot-core
const n8nBaseUrl = $env.N8N_WEBHOOK_URL || $env.WEBHOOK_URL || 'https://n8n.bot-appetit.fr';
const callbackUrl = `${n8nBaseUrl}/webhook/private-channel-callback`;

// Generate request ID
const requestId = 'req-' + Date.now() + '-' + Math.random().toString(36).substr(2, 9);

return {
  redis_message: {
    type: 'notification',
    actions: {
      create_private_channel: true
    },
    discord_user_id: validationData.discord_user_id,
    guild_id: validationData.guild_id,
    channel_type: validationData.channel_type,
    callback_url: callbackUrl,
    metadata: {
      request_id: requestId,
      project_id: validationData.project_id,
      recreated_from: validationData.old_channel_id,
      reason: 'unknown_channel_error',
      ...validationData.metadata
    }
  },
  request_id: requestId,
  validation_data: validationData,
  delete_result: deleteResult
};

// ============================================
// FORMAT SUCCESS RESPONSE
// ============================================

const prepareData = $('Prepare Redis Message').first().json;

return {
  success: true,
  status: 'recreating',
  message: 'Obsolete channel deleted. New channel creation requested.',
  request_id: prepareData.request_id,
  old_channel_id: prepareData.validation_data.old_channel_id,
  channel_type: prepareData.validation_data.channel_type
};

// ============================================
// FORMAT VALIDATION ERROR RESPONSE
// ============================================

const input = $input.first().json;

return {
  success: false,
  error: {
    code: input.error_code || 'VALIDATION_ERROR',
    message: input.message || 'Erreur de validation',
    http_status: 400
  }
};
